### 5. 테스트 파일 구조

`.fl` 테스트 파일 패턴 (v2_5_tests.fl 기준):

```freelang
# ================================================================
# FreeLang vX.Y.Z Tests (N개 무관용 테스트)
# ================================================================

# 각 테스트: fn test_XXX() 함수로 정의
fn test_break_exits_loop() {
  # 의도/규칙 설명
  let count = 0
  while count < 100 {
    if count == 5 { break }
    count = count + 1
  }
  assert_eq(count, 5, "break should exit at 5")  # assert_eq(실제, 기대, 메시지)
}

# 모든 테스트를 한꺼번에 실행하는 runner 함수
fn run_all_v2_6_tests() {
  test_break_exits_loop()
  test_another_test()
  println!("✅ All v2.6.0 tests passed!")
}

# 엔트리포인트 호출
run_all_v2_6_tests()
```

v2_4_tests.fl의 고급 패턴:
```freelang
#[cfg(test)]           # 테스트 마커 (어노테이션 스타일)
fn test_group_1_a1_return_early_exit() {
  fn get_value(x: i32): i32 {    # 타입 어노테이션 (파서가 무시)
    if x < 0 { return -1 }
    return x * 2
